 85	/** Copy all mirrored fields from active tab → flat state (for component reads). */
 86	function syncFlatStateFromTab(draft: ChatState, tab: 'think' | 'do') {
 87	  draft.sessionId = draft[tab].sessionId;
 88	  draft.messages = draft[tab].messages;
 89	  draft.isStreaming = draft[tab].isStreaming;
 90	  draft.isCompacting = draft[tab].isCompacting;
