 92	  draft.tokenUsage = draft[tab].tokenUsage;
 93	  draft.activeTokenUsage = draft[tab].activeTokenUsage;
 94	  draft.pendingInput = draft[tab].pendingInput;
 95	  draft.planMode = draft[tab].planMode;
 96	  draft.pendingQuestion = draft[tab].pendingQuestion;
 97	  draft.title = draft[tab].title;
 98	  draft.titleSource = draft[tab].titleSource;
 99	}
