202	let handshakeTimer: ReturnType<typeof setTimeout> | null = null;
203	
204	function clearHandshakeTimer() {
205	  if (handshakeTimer) {
206	    clearTimeout(handshakeTimer);
207	    handshakeTimer = null;
208	  }
209	}
210	
211	function clearAllInlineErrors(state: { messages: ChatMessage[] }): void {
212	  for (const msg of state.messages) {
213	    if (msg.inlineError) {
214	      msg.inlineError = undefined;
215	    }
216	  }
217	}
218	
219	function doSend(state: ChatState, content: string | ContentPart[], model: string) {
220	  const { sessionId } = state;
221	  const { thinkingEnabled } = useSettingsStore.getState();
222	
223	  clearHandshakeTimer();
224	  handshakeTimer = setTimeout(() => {
225	    const s = useChatStore.getState();
226	    if (s.isStreaming && !s.handshakeReceived) {
227	      bridge.abortChat();
228	      s.processEvent({
229	        type: "error",
230	        code: "HANDSHAKE_TIMEOUT",
231	        message: "Connection timed out.",
232	        phase: "runtime",
233	      });
234	    }
235	  }, HANDSHAKE_TIMEOUT_MS);
236	
237	  bridge.streamChat(content, model, thinkingEnabled, sessionId ?? undefined, state.activeTab);
238	}
