240	export const useChatStore = create<ChatState>((set, get) => ({
241	  sessionId: null,
242	  messages: [],
243	  isStreaming: false,
244	  isCompacting: false,
245	  handshakeReceived: false,
246	  draftMedia: [],
247	  lastStatus: null,
248	  tokenUsage: createEmptyTokenUsage(),
249	  activeTokenUsage: createEmptyTokenUsage(),
250	  pendingInput: null,
251	  queue: [],
252	  pendingQuestion: null,
253	  planMode: false,
254	  activeTab: 'think',
255	  title: undefined,
256	  titleSource: undefined,
257	  think: createEmptyTabState(),
258	  do: createEmptyTabState(),
259	  setActiveTab: (tab: 'think' | 'do') => {
260	    const state = get();
261	    if (state.activeTab === tab) return;
262	
263	    set(produce((draft: ChatState) => {
264	      // Save full outgoing tab state
265	      syncTabStateFromFlat(draft, draft.activeTab);
266	      // Load incoming tab state into flat
267	      syncFlatStateFromTab(draft, tab);
268	      draft.activeTab = tab;
269	    }));
270	
271	    bridge.setActiveTab(tab);
272	  },
273	  get currentTabState() {
274	    const s = get();
275	    return s[s.activeTab];
276	  },
277	
278	  initTabs: async () => {
279	    console.log('[Store] initTabs starting');
280	    const restored = await bridge.restoreTabState();
281	    console.log('[Store] restored:', JSON.stringify(restored));
282	    const { setActiveTab, loadSession } = get();
283	
284	    // Fetch histories concurrently and catch any errors (e.g., deleted sessions)
285	    const [thinkRes, doRes] = await Promise.allSettled([
286	      restored.thinkSessionId ? bridge.loadSessionHistory(restored.thinkSessionId) : Promise.resolve(null),
287	      restored.doSessionId ? bridge.loadSessionHistory(restored.doSessionId) : Promise.resolve(null),
288	    ]);
289	
290	    const thinkEvents = thinkRes.status === 'fulfilled' ? thinkRes.value : null;
291	    const doEvents = doRes.status === 'fulfilled' ? doRes.value : null;
292	
293	    console.log('[Store] thinkEvents count:', thinkEvents?.length ?? 0);
294	    console.log('[Store] doEvents count:', doEvents?.length ?? 0);
295	
296	    // Load think silently
297	    if (restored.thinkSessionId && thinkEvents && thinkEvents.length > 0) {
298	      console.log('[Store] loading Think session silently');
299	      set({ activeTab: 'think' });
300	      await loadSession(restored.thinkSessionId, thinkEvents);
301	    }
302	
303	    // Load do silently
304	    if (restored.doSessionId && doEvents && doEvents.length > 0) {
305	      console.log('[Store] loading Do session silently');
306	      set({ activeTab: 'do' });
307	      await loadSession(restored.doSessionId, doEvents);
308	    }
309	
310	    const finalTab = restored.activeTab ?? 'think';
311	    console.log('[Store] setting final activeTab to:', finalTab);
312	
313	    // Ensure local state matches; bypass setActiveTab to avoid early-return if already set
314	    set(produce((draft: ChatState) => {
315	      draft.activeTab = finalTab;
316	      syncFlatStateFromTab(draft, finalTab);
317	    }));
318	
319	    // Explicitly sync to backend - critical on reload when backend activeTabs is empty
320	    bridge.setActiveTab(finalTab);
321	    console.log('[Store] initTabs complete');
322	  },
323	
324	  sendMessage: (text) => {
325	    const { draftMedia, isStreaming } = get();
326	    const { currentModel } = useSettingsStore.getState();
327	
328	    const readyMedia = draftMedia.filter((m) => m.dataUri).map((m) => m.dataUri!);
329	    const content = readyMedia.length > 0 ? Content.build(text, readyMedia) : text;
330	
331	    if (Content.isEmpty(content)) {
332	      return;
333	    }
334	
335	    // If streaming, enqueue instead of sending
336	    if (isStreaming) {
337	      get().enqueue(content, currentModel);
338	      set({ draftMedia: [] });
339	      return;
340	    }
341	
342	    // Clear draft and set streaming state on active tab
343	    set(
344	      produce((draft: ChatState) => {
345	        clearAllInlineErrors(draft[draft.activeTab]);
346	        draft.draftMedia = [];
347	        draft[draft.activeTab].isStreaming = true;
348	        draft[draft.activeTab].pendingInput = { content, model: currentModel };
349	        syncFlatStateFromTab(draft, draft.activeTab);
350	        draft.handshakeReceived = false;
351	      }),
352	    );
353	    useApprovalStore.getState().clearRequests();
354	
355	    doSend(get(), content, currentModel);
356	  },
357	
358	  retryLastMessage: () => {
359	    const { pendingInput, isStreaming } = get();
360	
361	    if (isStreaming || !pendingInput) {
362	      return;
363	    }
364	
365	    // Remove failed assistant message and user message
366	    set(
367	      produce((draft: ChatState) => {
368	        const tab = draft[draft.activeTab];
369	        clearAllInlineErrors(tab);
370	        tab.isStreaming = true;
371	        const lastAssistant = tab.messages.at(-1);
372	        if (lastAssistant?.role === "assistant" && lastAssistant.inlineError) {
373	          tab.messages.pop();
374	          if (tab.messages.at(-1)?.role === "user") {
375	            tab.messages.pop();
376	          }
377	        }
378	        syncFlatStateFromTab(draft, draft.activeTab);
379	        draft.handshakeReceived = false;
380	      }),
381	    );
382	    useApprovalStore.getState().clearRequests();
383	
384	    doSend(get(), pendingInput.content, pendingInput.model);
385	  },
386	
387	  processEvent: (event) => {
388	    // Clear handshake timeout on receiving valid response
389	    if (event.type === "TurnBegin" || event.type === "StepBegin" || event.type === "ContentPart") {
390	      clearHandshakeTimer();
391	      set({ handshakeReceived: true });
392	    }
393	
394	    set(
395	      produce((draft: ChatState) => {
396	        // Route event to correct tab by explicit mode, then sessionId, then active tab fallback
397	        const targetTab = getTargetTab(event as any, {
398	          activeTab: draft.activeTab,
399	          thinkSessionId: draft.think.sessionId,
400	          doSessionId: draft.do.sessionId,
401	        });
402	        const activeTab = draft.activeTab;
403	
404	        // If the event targets the inactive tab, swap its state into the flat
405	        // scratch space so legacy handlers (which mutate flat state) operate on
406	        // the right tab. Then swap back.
407	        if (targetTab !== activeTab) {
408	          syncTabStateFromFlat(draft, activeTab);
409	          syncFlatStateFromTab(draft, targetTab);
410	        }
411	
412	        processEvent(draft, event);
413	
414	        syncTabStateFromFlat(draft, targetTab);
415	
416	        if (targetTab !== activeTab) {
417	          syncFlatStateFromTab(draft, activeTab);
418	        }
419	
420	        // Invariant: flat state must always reflect the active tab
421	        if (draft.messages !== draft[draft.activeTab].messages) {
422	          console.warn(
423	            `[chat.store invariant] messages mismatch: flat state points to ${draft.messages === draft.think.messages ? 'think' : draft.messages === draft.do.messages ? 'do' : 'unknown'}, activeTab=${draft.activeTab}`,
424	          );
425	        }
426	        if (draft.isStreaming !== draft[draft.activeTab].isStreaming) {
427	          console.warn(
428	            `[chat.store invariant] isStreaming mismatch: flat=${draft.isStreaming}, ${draft.activeTab}.isStreaming=${draft[draft.activeTab].isStreaming}`,
429	          );
430	        }
431	        if (draft.think.messages.some((m: any) => (m as any)._sessionId && (m as any)._sessionId === draft.do.sessionId)) {
432	          console.warn(`[chat.store invariant] Think tab contains messages from Do session ${draft.do.sessionId}`);
433	        }
434	        if (draft.do.messages.some((m: any) => (m as any)._sessionId && (m as any)._sessionId === draft.think.sessionId)) {
435	          console.warn(`[chat.store invariant] Do tab contains messages from Think session ${draft.think.sessionId}`);
436	        }
437	      }),
438	    );
439	
440	    // Auto-send next queued item when streaming ends (complete, abort, or error).
441	    // history_restored does NOT trigger auto-send — the user is reviewing history.
442	    if (event.type === "stream_complete" || event.type === "stream_aborted" || event.type === "error") {
443	      const { queue, isStreaming: stillStreaming } = get();
444	      if (!stillStreaming && queue.length > 0) {
445	        setTimeout(() => get().sendNextQueued(), 50);
446	      }
447	    }
448	  },
449	
450	  loadSession: async (sessionId, events, titleInfo) => {
451	    clearHandshakeTimer();
452	    
453	    // Abort any ongoing stream when switching sessions
454	    const { isStreaming: wasStreaming } = get();
455	    if (wasStreaming) {
456	      await bridge.abortChat();
457	    }
458	    
459	    set(produce((draft: ChatState) => {
460	      // Reset active tab state
461	      draft[draft.activeTab] = createEmptyTabState();
462	      draft[draft.activeTab].sessionId = sessionId;
463	      draft[draft.activeTab].title = titleInfo?.title;
464	      draft[draft.activeTab].titleSource = titleInfo?.titleSource;
465	      // Sync flat state from active tab
466	      syncFlatStateFromTab(draft, draft.activeTab);
467	      // Reset globals
468	      draft.handshakeReceived = false;
469	      draft.draftMedia = [];
470	      draft.queue = [];
471	    }));
472	    useApprovalStore.getState().clearRequests();
473	    bridge.clearTrackedFiles();
474	
475	    for (const event of events) {
476	      // Inject sessionId for proper tab routing during history load
477	      (event as any)._sessionId = sessionId;
478	      get().processEvent(event);
479	    }
480	
481	    // All steps are finished when loading from history
482	    set(
483	      produce((draft: ChatState) => {
484	        for (const msg of draft.messages) {
485	          if (msg.steps) {
486	            for (const step of msg.steps) {
487	              for (const item of step.items) {
488	                if (item.type === "text" || item.type === "thinking") {
489	                  item.finished = true;
490	                }
491	              }
492	            }
493	          }
494	        }
495	        draft.isStreaming = false;
496	        draft.isCompacting = false;
497	        draft.pendingQuestion = null;
498	        // Sync back to active tab
499	        syncTabStateFromFlat(draft, draft.activeTab);
500	      }),
501	    );
502	    useApprovalStore.getState().clearRequests();
503	  },
504	
505	  startNewConversation: async () => {
506	    clearHandshakeTimer();
507	    
508	    // Abort any ongoing stream before starting new conversation
509	    const { isStreaming: wasStreaming } = get();
510	    if (wasStreaming) {
511	      bridge.abortChat();
512	    }
513	    
514	    await bridge.resetSession();
515	    await bridge.clearTrackedFiles();
516	    set(produce((draft: ChatState) => {
517	      draft[draft.activeTab] = createEmptyTabState();
518	      syncFlatStateFromTab(draft, draft.activeTab);
519	      draft.handshakeReceived = false;
520	      draft.draftMedia = [];
521	      draft.queue = [];
522	    }));
523	    useApprovalStore.getState().clearRequests();
524	  },
525	
526	  abort: () => {
527	    clearHandshakeTimer();
528	    bridge.abortChat();
529	    set(produce((draft: ChatState) => {
530	      draft[draft.activeTab].pendingQuestion = null;
531	      syncFlatStateFromTab(draft, draft.activeTab);
532	    }));
533	    useApprovalStore.getState().clearRequests();
534	  },
535	
536	  addDraftMedia: (id, dataUri) => {
537	    set((s) => ({ draftMedia: [...s.draftMedia, { id, dataUri }] }));
538	  },
539	
540	  updateDraftMedia: (id, dataUri) => {
541	    set((s) => ({
542	      draftMedia: s.draftMedia.map((m) => (m.id === id ? { ...m, dataUri } : m)),
543	    }));
544	  },
545	
546	  removeDraftMedia: (id) => {
547	    set((s) => ({ draftMedia: s.draftMedia.filter((m) => m.id !== id) }));
548	  },
549	
550	  clearDraftMedia: () => {
551	    set({ draftMedia: [] });
552	  },
553	
554	  getMediaInConversation: () => {
555	    const { messages, draftMedia } = get();
556	
557	    let hasImage = false;
558	    let hasVideo = false;
559	
560	    for (const item of draftMedia) {
561	      if (!item.dataUri) {
562	        continue;
563	      }
564	      if (item.dataUri.startsWith("data:image/")) {
565	        hasImage = true;
566	      } else if (item.dataUri.startsWith("data:video/")) {
567	        hasVideo = true;
568	      }
569	    }
570	
571	    for (const msg of messages) {
572	      if (Content.hasImages(msg.content)) {
573	        hasImage = true;
574	      }
575	      if (Content.hasVideos(msg.content)) {
576	        hasVideo = true;
577	      }
578	      if (hasImage && hasVideo) {
579	        break;
580	      }
581	    }
582	
583	    return { hasImage, hasVideo };
584	  },
585	
586	  hasProcessingMedia: () => {
587	    return get().draftMedia.some((m) => !m.dataUri);
588	  },
589	
590	  rollbackInput: (content) => {
591	    const { currentModel } = useSettingsStore.getState();
592	    set(produce((draft: ChatState) => {
593	      draft[draft.activeTab].pendingInput = { content, model: currentModel };
594	      syncFlatStateFromTab(draft, draft.activeTab);
595	    }));
596	  },
597	
598	  respondQuestion: async (answers) => {
599	    const { pendingQuestion } = get();
600	    if (!pendingQuestion) return;
601	    await bridge.respondQuestion(pendingQuestion.id, pendingQuestion.id, answers);
602	    set(produce((draft: ChatState) => {
603	      draft[draft.activeTab].pendingQuestion = null;
604	      syncFlatStateFromTab(draft, draft.activeTab);
605	    }));
606	  },
607	
608	  setTitle: (sessionId, title, source) => {
609	    if (!sessionId) return;
610	    set(
611	      produce((draft: ChatState) => {
612	        const targetTab =
613	          draft.think.sessionId === sessionId ? 'think' :
614	          draft.do.sessionId === sessionId ? 'do' :
615	          draft.activeTab;
616	
617	        draft[targetTab].title = title;
618	        draft[targetTab].titleSource = source;
619	        if (targetTab === draft.activeTab) {
620	          draft.title = title;
621	          draft.titleSource = source;
622	        }
623	      }),
624	    );
625	  },
626	
627	  renameSession: async (sessionId, newTitle) => {
628	    if (!sessionId) return;
629	    const trimmed = newTitle.trim();
630	    const source: TitleSource = trimmed ? 'user' : 'fallback';
631	    const title = trimmed;
632	
633	    get().setTitle(sessionId, title || "Untitled", source);
634	    await bridge.writeSessionMetadata(sessionId, title, source);
635	  },
636	
637	  enqueue: (content, model) => {
638	    set((s) => ({
639	      queue: [...s.queue, { id: crypto.randomUUID(), content, model }],
640	    }));
641	  },
642	
643	  removeFromQueue: (id) => {
644	    set((s) => ({ queue: s.queue.filter((q) => q.id !== id) }));
645	  },
646	
647	  editQueueItem: (id, content) => {
